CREATE TABLE tenants (id BIGINT AUTO_INCREMENT PRIMARY KEY, company_name VARCHAR(150) NOT NULL, subdomain VARCHAR(80) NOT NULL UNIQUE, subscription_plan VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, created_at DATETIME NOT NULL, active BOOLEAN NOT NULL, CONSTRAINT fk_user_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE connections (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(190), phone VARCHAR(50), company_name VARCHAR(150), source VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, assigned_to_user_id BIGINT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX ix_connections_tenant (tenant_id));
CREATE TABLE deal_flows (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, connection_id BIGINT NOT NULL, amount DECIMAL(19,2) NOT NULL, stage VARCHAR(30) NOT NULL, assigned_to_user_id BIGINT, expected_close_date DATE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX ix_deal_tenant (tenant_id));
CREATE TABLE touchpoints (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, related_connection_id BIGINT, related_deal_id BIGINT, description TEXT NOT NULL, created_by_user_id BIGINT NOT NULL, created_at DATETIME NOT NULL, due_date DATETIME, completed BOOLEAN NOT NULL, INDEX ix_touch_tenant (tenant_id));
CREATE TABLE workflow_rules (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL, trigger_event VARCHAR(60) NOT NULL, condition_field VARCHAR(100), condition_value VARCHAR(255), action_type VARCHAR(60) NOT NULL, action_value VARCHAR(255), active BOOLEAN NOT NULL, INDEX ix_rule_tenant (tenant_id));
